item.aggregated_output:
    "mechanism": "acceptance_inference_from_position_delta",
    "description": "Infers how many draft tokens were accepted by computing len(generated_token_ids) delta between consecutive draft() calls, minus 1 (the ordinary fallback token from the target model). No access to target logits or private state needed \u2014 uses only the public draft(state) interface.",
    "acceptance_inference": {
      "formula": "accepted = len(current_ids) - len(previous_ids) - 1",
      "sanity_checks": [
        "accepted >= 0",
        "accepted <= estimated_proposed_tokens"
      ]
    },
    "reset_detection": {
      "signals": [
        "first_call (no prior state)",
        "empty_generated_token_ids (new question start)",
        "question_text_changed (hash comparison)",
        "position_went_backward (shortened history / rollback)",
        "decoded_text_got_shorter"
      ],
      "what_resets": [
        "per-question draft counters",
        "recent sliding acceptance window"
      ],
      "what_persists": [
        "per-trigger acceptance statistics",
        "per-strategy acceptance statistics",
        "global total counters"
      ]
    },
    "adaptation_actions": [
      "Reorder templates by observed acceptance rate (proven good \u2192 unknown \u2192 proven poor)",
      "Select among matching templates by expected value (acceptance_rate * continuation_length)",
      "Conservative: only rank after 5+ observations per trigger"
    ],
    "what_is_NOT_adapted": [
      "No hard suppression of low-performing triggers (all remain eligible)",
      "No global draft length factor (found to be harmful in testing)",
      "No strategy disabling (found to hurt more than help)"
    ],
    "cpu_testbed_results": {
      "mc_reasoning_cross_question_learning": "+1.7% speedup",
      "mixed_format_overall": "+0.4% speedup",
      "noise_0_percent": "+1.8% speedup",
      "noise_10_percent": "+0.9% speedup",
      "noise_20_percent": "+0.5% speedup",
      "open_ended": "neutral (+0.0%)",
      "short_answer": "neutral (+0.0%)",
      "no_regression": "true \u2014 adaptation never reduces performance"
    },
    "complexity": {
      "per_call_overhead": "~100 microseconds (negligible vs model inference)",
      "state_memory": "~600 bytes (bounded by fixed template set size)",
      "per_call_ops": "O(n_templates) for ranking, O(1) for observation"
    },
    "state_leakage_risks": [
      {
        "risk": "Cross-question stat carryover",
        "severity": "low",
        "description": "Per-trigger stats persist across questions. Could bias early drafts of a new question toward the previous question's format.",
        "mitigation": "Conservative ranking (5+ observations before trusting stats). Recent window resets per question. Bias is toward better-performing templates which should generalize."
      },
      {
        "risk": "Position delta inference error",
        "severity": "medium",
        "description": "If generated_token_ids includes prompt tokens or special tokens, acceptance inference will be wrong.",
        "mitigation": "Sanity checks: accepted >= 0, accepted <= proposed. Conservative ranking thresholds tolerate some noise. Wrong inference just means slower adaptation, not incorrect behavior."
      },
      {
        "risk": "Reset detection false positive",
        "severity": "low",
        "description": "Might incorrectly reset per-question state. Just loses history \u2014 safe.",
        "mitigation": "Multiple redundant reset signals. False positive is safer than false negative."
      },
      {
        "risk": "Tokenizer mismatch in proposed token estimate",
        "severity": "medium",
        "description": "We estimate proposed tokens as word count, but real tokenizer uses subwords.",
        "mitigation": "Only used for sanity cap (accepted <= proposed). Word count <= token count is conservative. Position delta itself uses real token IDs and is accurate."
      }
    ]
  }
}
